import { test, expect } from '@playwright/test';

test.describe('Product Detail Navigation', () => {
  const BASE_URL = 'https://www.saucedemo.com';
  const USERNAME = 'standard_user';
  const PASSWORD = 'secret_sauce';

  test.beforeEach(async ({ page }) => {
    await page.goto(BASE_URL);

    // Login
    await page.getByLabel('Username').fill(USERNAME);
    await page.getByLabel('Password').fill(PASSWORD);
    await page.getByRole('button', { name: /login/i }).click();

    // Wait for inventory page to load
    await page.waitForURL('**/inventory.html');
  });

  test('should navigate to product detail page when clicking first product name', async ({ page }) => {
    // Click the first product name
    const firstProductName = page.locator('.inventory_item_name').first();
    await firstProductName.click();

    // Verify URL contains 'inventory-item.html'
    await expect(page).toHaveURL(/inventory-item\.html/);
  });

  test('should return to inventory page when clicking back button', async ({ page }) => {
    // Navigate to product detail page
    const firstProductName = page.locator('.inventory_item_name').first();
    await firstProductName.click();

    // Verify we're on product detail page
    await expect(page).toHaveURL(/inventory-item\.html/);

    // Click back button
    await page.locator('[data-test="back-to-products"]').click();

    // Verify URL contains '/inventory.html'
    await expect(page).toHaveURL(/\/inventory\.html/);

    // Verify 'Products' title is displayed
    await expect(page.locator('.title')).toContainText('Products');
  });

  test('should maintain product catalogue state after returning from detail page', async ({ page }) => {
    // Get initial product count
    const initialProductCount = await page.locator('.inventory_item').count();

    // Navigate to first product
    const firstProductName = page.locator('.inventory_item_name').first();
    await firstProductName.click();

    // Return to inventory
    await page.locator('[data-test="back-to-products"]').click();

    // Verify we're back on inventory page
    await expect(page).toHaveURL(/\/inventory\.html/);

    // Verify product count is the same
    const finalProductCount = await page.locator('.inventory_item').count();
    expect(finalProductCount).toBe(initialProductCount);
  });
});
